import{_ as n,C as d,o as a,c as l,a4 as o,b as r,w as e,a as i,E as c,a5 as p}from"./chunks/framework.BRzJ4ijD.js";const m=JSON.parse('{"title":"DNS: 名字解析全链路 / 缓存 / CDN 调度 / DNSSEC","description":"","frontmatter":{},"headers":[],"relativePath":"networking/ip/dns.md","filePath":"networking/ip/dns.md","lastUpdated":1788475713000}'),u={name:"networking/ip/dns.md"};function h(D,t,S,g,T,A){const s=d("Mermaid");return a(),l("div",null,[t[1]||(t[1]=o(`<h1 id="dns-名字解析全链路-缓存-cdn-调度-dnssec" tabindex="-1">DNS: 名字解析全链路 / 缓存 / CDN 调度 / DNSSEC <a class="header-anchor" href="#dns-名字解析全链路-缓存-cdn-调度-dnssec" aria-label="Permalink to &quot;DNS: 名字解析全链路 / 缓存 / CDN 调度 / DNSSEC&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>浏览器里输入 <code>https://api.example.com</code> 到发出第一个 TCP SYN 之间，发生了一次<strong>全球分布式 KV 查询</strong>：stub resolver → 递归解析器 → 根 → TLD → 权威服务器，每层都有缓存。DNS 不只是一个&quot;把域名换成 IP 的协议&quot;，它同时是 <strong>CDN 调度的入口</strong>（CNAME 链 + GeoDNS + 短 TTL）、<strong>服务发现的骨架</strong>（K8s 里 <code>svc.namespace.svc.cluster.local</code>）、以及<strong>被攻击面</strong>（缓存投毒、DDoS、域名劫持）。读完这一章，你应能讲清一条 DNS 查询走了哪些节点、为什么 TTL 是运维最敏感的旋钮、CDN 怎么靠 CNAME/TTL 玩流量调度，以及 DNSSEC / DoH / HTTPDNS 各自防住什么。</p><p>读完应能：</p><ol><li>画出一次 <code>dig www.example.com</code> 的完整路径，区分递归解析器 / 根 / TLD / 权威四种角色。</li><li>解释 TTL 与 negative TTL 如何决定&quot;故障切换速度&quot;与&quot;缓存压力&quot;的取舍。</li><li>讲清 CDN 如何用 CNAME + GeoDNS + 短 TTL 把用户调度到最近的边缘节点。</li><li>说清缓存投毒 / Kaminsky 攻击的机制，以及 DNSSEC、0x20 编码、DoH/DoT 分别堵住哪个洞。</li><li>读懂 K8s 内部 DNS 与 CoreDNS 的解析路径，知道为什么内部 DNS 用头部/尾部匹配而不是域名后缀。</li></ol><hr><h2 id="一、为什么不能只用-hosts-文件" tabindex="-1">一、为什么不能只用 hosts 文件 <a class="header-anchor" href="#一、为什么不能只用-hosts-文件" aria-label="Permalink to &quot;一、为什么不能只用 hosts 文件&quot;">​</a></h2><p>TCP/IP 只认 IP；人的记忆只认名字。两个极端方案都不行：</p><ul><li><strong>静态 hosts 文件</strong>：无法随故障迁移，无法按地理位置返回不同地址，无法集中运维——只能在单机/小型内网用。</li><li><strong>每次全量广播&quot;谁叫什么&quot;</strong>：条目数随域名数量爆炸（今天约 3.6 亿个注册域名），且每台机器都存全量不可扩展。</li></ul><p>DNS 的工程答案是把名字空间做成<strong>树</strong>，把解析做成<strong>缓存+分层授权</strong>：没有任何一台机器知道全部名字，但任何一台机器都能在有限步数内把问题&quot;问对地方&quot;。</p><h2 id="二、名字空间-一棵树-逐层授权" tabindex="-1">二、名字空间：一棵树，逐层授权 <a class="header-anchor" href="#二、名字空间-一棵树-逐层授权" aria-label="Permalink to &quot;二、名字空间：一棵树，逐层授权&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                  .  (根, 13 组 anycast 根服务器)</span></span>
<span class="line"><span>        ┌──────────┼──────────┐</span></span>
<span class="line"><span>       com        org        cn</span></span>
<span class="line"><span>        │                      │</span></span>
<span class="line"><span>     example.com           aliyun.com</span></span>
<span class="line"><span>        │                      │</span></span>
<span class="line"><span>    api.example.com      www.aliyun.com</span></span></code></pre></div><ul><li><strong>FQDN（Fully Qualified Domain Name）</strong>：<code>api.example.com.</code>，末尾的点表示根。</li><li>每一层 zone 对其子树有<strong>权威（authoritative）</strong>：<code>com</code> 权威管理 <code>example.com</code> 的 NS 记录指向谁，<code>example.com</code> 的权威服务器管理 <code>api</code> / <code>www</code> 等记录。</li><li>关键设计：<strong>委托（delegation）不是复制数据，而是复制&quot;指针&quot;（NS 记录 + glue A 记录）</strong>。所以 <code>com</code> 服务器不需要知道 <code>api.example.com</code> 的 IP。</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>根服务器只有 13 个&quot;名字&quot;（a.root-servers.net 等），但背后是 1900+ 个 anycast 实例，全球同播。根不存具体域名，只存 TLD 的 NS 指针——这是&quot;分层让世界可扩展&quot;的教科书例子。</p></div><h2 id="三、一次查询的完整路径" tabindex="-1">三、一次查询的完整路径 <a class="header-anchor" href="#三、一次查询的完整路径" aria-label="Permalink to &quot;三、一次查询的完整路径&quot;">​</a></h2>`,15)),(a(),r(p,null,{default:e(()=>[c(s,{id:"mermaid-90",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20App%20as%20%E5%BA%94%E7%94%A8%20(%E6%B5%8F%E8%A7%88%E5%99%A8)%0A%20%20%20%20participant%20Stub%20as%20stub%20resolver%0A%20%20%20%20participant%20Rec%20as%20%E9%80%92%E5%BD%92%E8%A7%A3%E6%9E%90%E5%99%A8%20(8.8.8.8%20%2F%20%E5%86%85%E7%BD%91%20DNS)%0A%20%20%20%20participant%20Root%20as%20%E6%A0%B9%E6%9C%8D%E5%8A%A1%E5%99%A8%0A%20%20%20%20participant%20TLD%20as%20TLD%20%E6%9C%8D%E5%8A%A1%E5%99%A8%20(.com)%0A%20%20%20%20participant%20Auth%20as%20%E6%9D%83%E5%A8%81%E6%9C%8D%E5%8A%A1%E5%99%A8%20(example.com)%0A%0A%20%20%20%20App-%3E%3EStub%3A%20getaddrinfo(%22www.example.com%22)%0A%20%20%20%20Stub-%3E%3ERec%3A%20%E6%9F%A5%E8%AF%A2%20www.example.com%20A%0A%20%20%20%20Rec-%3E%3ERoot%3A%20%E9%97%AE%20.com%20%E7%9A%84%20NS%3F%0A%20%20%20%20Root--%3E%3ERec%3A%20.com%20NS%20%E5%88%97%E8%A1%A8%0A%20%20%20%20Rec-%3E%3ETLD%3A%20%E9%97%AE%20example.com%20%E7%9A%84%20NS%3F%0A%20%20%20%20TLD--%3E%3ERec%3A%20example.com%20NS%20%2B%20glue%20A%0A%20%20%20%20Rec-%3E%3EAuth%3A%20%E9%97%AE%20www.example.com%20A%3F%0A%20%20%20%20Auth--%3E%3ERec%3A%2093.184.216.34%20(TTL%3D300)%0A%20%20%20%20Rec--%3E%3EStub%3A%20%E7%AD%94%E6%A1%88%20%2B%20%E7%BC%93%E5%AD%98%0A%20%20%20%20Stub--%3E%3EApp%3A%2093.184.216.34%0A"})]),fallback:e(()=>[...t[0]||(t[0]=[i(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=o(`<p>几个必须分清的概念：</p><table tabindex="0"><thead><tr><th>角色</th><th>干什么</th><th>谁跑</th></tr></thead><tbody><tr><td><strong>stub resolver</strong></td><td>把查询交给递归器，自己不做迭代</td><td>操作系统 libc / 应用 SDK</td></tr><tr><td><strong>递归解析器</strong></td><td>替客户端迭代问根→TLD→权威，并缓存</td><td>ISP DNS、8.8.8.8、内网 DNS、CoreDNS(forward)</td></tr><tr><td><strong>权威服务器</strong></td><td>对自己 zone 内的记录给出最终答案</td><td>云 DNS、自建 NS、CDN 的权威</td></tr><tr><td><strong>缓存</strong></td><td>TTL 内直接回答案，不再向上游</td><td>递归器每层都有；浏览器/OS 还有自己的缓存</td></tr></tbody></table><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>客户端拿到的不一定&quot;最新&quot;：递归器 TTL 内不会回源。<strong>改记录后没切流量，90% 是 TTL 还没过</strong>；线上变更域名指向必须&quot;提前一个 TTL 周期改&quot;，否则要等最长 TTL 才能全部生效。</p></div><h2 id="四、记录类型速查" tabindex="-1">四、记录类型速查 <a class="header-anchor" href="#四、记录类型速查" aria-label="Permalink to &quot;四、记录类型速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>含义</th><th>典型用途</th></tr></thead><tbody><tr><td>A / AAAA</td><td>IPv4 / IPv6 地址</td><td>直接指向</td></tr><tr><td>CNAME</td><td>别名 → 另一个名字</td><td><code>www</code> → CDN 域名</td></tr><tr><td>NS</td><td>zone 的权威服务器</td><td>委托</td></tr><tr><td>MX</td><td>邮件服务器（含优先级）</td><td>邮件路由</td></tr><tr><td>TXT</td><td>任意文本</td><td>SPF/DKIM/DMARC 验证、证书验证</td></tr><tr><td>SRV</td><td>服务 + 端口</td><td>老式服务发现</td></tr><tr><td>SOA</td><td>zone 版本/刷新参数</td><td>权威元数据、主从同步</td></tr><tr><td>CAA</td><td>允许哪些 CA 发证书</td><td>防证书误发</td></tr><tr><td>DS / DNSKEY / RRSIG</td><td>DNSSEC 链</td><td>签名验证</td></tr><tr><td>PTR</td><td>反向：IP → 名字</td><td>反垃圾邮件、日志审计</td></tr></tbody></table><h2 id="五、ttl-dns-里最贵的旋钮" tabindex="-1">五、TTL：DNS 里最贵的旋钮 <a class="header-anchor" href="#五、ttl-dns-里最贵的旋钮" aria-label="Permalink to &quot;五、TTL：DNS 里最贵的旋钮&quot;">​</a></h2><p>缓存窗口 = 故障窗口。</p><ul><li><strong>TTL 大（如 86400）</strong>：缓存命中率高、权威服务器压力小，但故障切换要等一天。</li><li><strong>TTL 小（如 30-60s）</strong>：切换快，但权威 QPS 暴涨，且 DDoS 放大器效应更强。</li><li><strong>negative TTL（SOA 里的 MINIMUM）</strong>：记录不存在的缓存时长——配错会让&quot;新域名/新记录&quot;延迟几小时才可见。</li></ul><p>CDN 的经典玩法：<strong>权威侧 CNAME 到调度域名 + 短 TTL + GeoDNS/EDNS Client Subnet</strong>。</p><ol><li><code>www.example.com CNAME www.example.com.cdn.example.net</code>（TTL 300s）；</li><li>递归器按客户端出口 IP 所在区域，让 CDN 权威返回<strong>最近的边缘节点 IP</strong>；</li><li>边缘节点本身故障时，CDN 改权威记录 + 靠边缘健康检查，在 TTL 内把流量切走。</li></ol><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>高可用 DNS 的三板斧：<strong>主备双权威（不同机房 + anycast）</strong>、<strong>监控 TTL 一致性</strong>、<strong>把关键域名 TTL 降到 60s 内并提前演练切换</strong>。</p></div><h2 id="六、dns-与-cdn-服务发现的工程协同" tabindex="-1">六、DNS 与 CDN / 服务发现的工程协同 <a class="header-anchor" href="#六、dns-与-cdn-服务发现的工程协同" aria-label="Permalink to &quot;六、DNS 与 CDN / 服务发现的工程协同&quot;">​</a></h2><h3 id="_6-1-内部服务发现" tabindex="-1">6.1 内部服务发现 <a class="header-anchor" href="#_6-1-内部服务发现" aria-label="Permalink to &quot;6.1 内部服务发现&quot;">​</a></h3><p>K8s 里 <code>my-svc.default.svc.cluster.local</code> 走 CoreDNS：</p><ul><li><code>svc</code> 记录返回 Service ClusterIP（A 记录），<code>endpoints</code> 变化时 CoreDNS 动态更新；</li><li>Pod 用 <code>ndots:5</code> 逐级尝试搜索域，这就是&quot;为什么 Pod 里 ping 短名字比 ping 全名慢&quot;的原因；</li><li>大规模场景的坑：<strong>DNS 缓存未及时失效 → 服务发现延迟</strong>。解法是缩短内部 TTL、事件驱动刷新（而非轮询）、必要时用 service mesh 的 xDS 直连替代 DNS。</li></ul><h3 id="_6-2-dns-负载均衡-最便宜的一层-lb" tabindex="-1">6.2 DNS 负载均衡（最便宜的一层 LB） <a class="header-anchor" href="#_6-2-dns-负载均衡-最便宜的一层-lb" aria-label="Permalink to &quot;6.2 DNS 负载均衡（最便宜的一层 LB）&quot;">​</a></h3><p>权威服务器按策略返回不同 IP：轮询、按地域、按权重、按健康状态。特点：</p><ul><li>优点：零额外硬件、天然分布式、客户端就近；</li><li>缺点：<strong>粒度是&quot;一次解析&quot;而非&quot;一个连接&quot;</strong>——客户端（和递归器）会缓存结果，长连接场景下流量可能不均衡；依赖 TTL 收敛，秒级不精确。</li></ul><p>所以生产架构通常是：<strong>DNS 负责&quot;就近&quot;粗调度，L4/L7 LB 负责&quot;精确&quot;负载均衡</strong>。</p><h2 id="七、安全-投毒、放大、劫持" tabindex="-1">七、安全：投毒、放大、劫持 <a class="header-anchor" href="#七、安全-投毒、放大、劫持" aria-label="Permalink to &quot;七、安全：投毒、放大、劫持&quot;">​</a></h2><h3 id="_7-1-缓存投毒与-kaminsky-攻击" tabindex="-1">7.1 缓存投毒与 Kaminsky 攻击 <a class="header-anchor" href="#_7-1-缓存投毒与-kaminsky-攻击" aria-label="Permalink to &quot;7.1 缓存投毒与 Kaminsky 攻击&quot;">​</a></h3><p>攻击者伪造 DNS 应答，让递归器缓存错误映射。关键点：应答必须匹配<strong>事务 ID + 查询的源端口 + 问题区</strong>。老版本递归器源端口固定，事务 ID 只有 16bit，攻击者暴力猜 ID 并提前把&quot;额外区&quot;的 NS 记录塞进缓存——这就是 2008 年 Kaminsky 攻击：<strong>不需要猜中目标记录，只需把权威 NS 指向攻击者服务器</strong>，之后整个 zone 的查询都被劫持。</p><p>防御：</p><ul><li><strong>源端口随机化 + 0x20 编码</strong>（查询名随机大小写，应答必须匹配）：把猜测空间从 2^16 撑到 2^28+；</li><li><strong>DNSSEC</strong>：权威对记录签名，递归器验签——这是根治方案；</li><li><strong>DoH/DoT</strong>：加密传输，中间人无法篡改/观测查询（也顺带解决隐私）。</li></ul><h3 id="_7-2-反射放大-ddos" tabindex="-1">7.2 反射放大 DDoS <a class="header-anchor" href="#_7-2-反射放大-ddos" aria-label="Permalink to &quot;7.2 反射放大 DDoS&quot;">​</a></h3><p>DNS UDP 应答可以比查询大几十倍（ANY 查询、大 TXT 记录），攻击者伪造源 IP 打任意目标。缓解：<strong>关闭 ANY、限制单客户端 QPS、响应限速、DNSSEC 减小放大比、UDP 源端口随机</strong>。</p><h3 id="_7-3-国内-污染-与-httpdns" tabindex="-1">7.3 国内&quot;污染&quot;与 HTTPDNS <a class="header-anchor" href="#_7-3-国内-污染-与-httpdns" aria-label="Permalink to &quot;7.3 国内&quot;污染&quot;与 HTTPDNS&quot;">​</a></h3><p>GFW 和部分 ISP 对 UDP/53 明文查询做关键字污染，返回错误 IP。工程对策：</p><ul><li><strong>HTTPDNS</strong>：客户端直接 HTTPS 请求调度服务器（如 <code>203.107.1.33</code> 之类固定 IP），拿到 IP 后绕过系统 DNS 直连——移动 App 标配；</li><li><strong>DoH/DoT</strong>：加密通道使污染失效（但可被 SNI/证书检测针对性阻断）；</li><li><strong>域名分域</strong>：权威侧按 EDNS Client Subnet 返回公网/内网地址。</li></ul><h2 id="八、一页速查" tabindex="-1">八、一页速查 <a class="header-anchor" href="#八、一页速查" aria-label="Permalink to &quot;八、一页速查&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>查询路径:  stub → 递归器 → 根 → TLD → 权威 → 回填缓存</span></span>
<span class="line"><span>性能关键:  缓存命中(TTL) / anycast 就近 / 权威 QPS</span></span>
<span class="line"><span>调度手段:  CNAME 链 / GeoDNS / ECS / 短 TTL + 健康检查</span></span>
<span class="line"><span>故障注意:  改记录提前 1 个 TTL / negative TTL 别配太大</span></span>
<span class="line"><span>安全防线:  源端口随机 + 0x20 / DNSSEC 签名 / DoH/DoT / HTTPDNS</span></span>
<span class="line"><span>服务发现:  K8s CoreDNS + ndots / 事件驱动刷新 / mesh xDS 直连</span></span></code></pre></div><p>下一篇: <a href="./nat">NAT 与 conntrack</a>。</p>`,32))])}const E=n(u,[["render",h]]);export{m as __pageData,E as default};
